#include <Wire.h>
#include <IRremote.hpp>

// ===== PINS =====
#define IR_LED_PIN 3
#define JOY_X A0
#define JOY_Y A1

// LIS3DHTR address (try 0x19 if not working)
#define LIS_ADDR 0x18

int joyX, joyY;
int16_t accX, accY, accZ;

void setup() {
  Serial.begin(9600);

  // IR start
  IrSender.begin(IR_LED_PIN);

  // I2C start
  Wire.begin();

  // ===== INIT LIS3DHTR =====
  Wire.beginTransmission(LIS_ADDR);
  Wire.write(0x20);      // CTRL_REG1
  Wire.write(0x57);      // Normal mode, enable X Y Z
  Wire.endTransmission();

  Serial.println("SYSTEM READY");
}

void loop() {

  // ===== READ JOYSTICK =====
  joyX = analogRead(JOY_X);
  joyY = analogRead(JOY_Y);

  // ===== READ LIS3DHTR =====
  Wire.beginTransmission(LIS_ADDR);
  Wire.write(0x28 | 0x80);   // auto increment
  Wire.endTransmission(false);
  Wire.requestFrom(LIS_ADDR, 6);

  accX = Wire.read() | (Wire.read() << 8);
  accY = Wire.read() | (Wire.read() << 8);
  accZ = Wire.read() | (Wire.read() << 8);

  // ===== PRINT CLEAN =====
  Serial.print("JX:"); Serial.print(joyX);
  Serial.print(" JY:"); Serial.print(joyY);

  Serial.print(" | AX:"); Serial.print(accX);
  Serial.print(" AY:"); Serial.print(accY);
  Serial.print(" AZ:"); Serial.print(accZ);

  Serial.print(" | ");

  // ===== CONTROL LOGIC =====

  // 🎮 Joystick priority
  if (joyX > 600) {
    Serial.println("RIGHT");
    IrSender.sendNEC(0x10, 0xA1, 0);

  } else if (joyX < 400) {
    Serial.println("LEFT");
    IrSender.sendNEC(0x10, 0xA2, 0);

  } else if (joyY > 600) {
    Serial.println("UP");
    IrSender.sendNEC(0x10, 0xA3, 0);

  } else if (joyY < 400) {
    Serial.println("DOWN");
    IrSender.sendNEC(0x10, 0xA4, 0);
  }

  // 📐 If joystick centered → use accelerometer
  else {

    if (accX > 2000) {
      Serial.println("TILT RIGHT");
      IrSender.sendNEC(0x10, 0xB1, 0);

    } else if (accX < -2000) {
      Serial.println("TILT LEFT");
      IrSender.sendNEC(0x10, 0xB2, 0);

    } else if (accY > 2000) {
      Serial.println("TILT UP");
      IrSender.sendNEC(0x10, 0xB3, 0);

    } else if (accY < -2000) {
      Serial.println("TILT DOWN");
      IrSender.sendNEC(0x10, 0xB4, 0);

    } else {
      Serial.println("STOP");
      IrSender.sendNEC(0x10, 0xA0, 0);
    }
  }

  delay(200);   // clean output
}
